def scan_workspace(workspace_path: str, ignore_list: list = ['.git', 'node_modules', '__pycache__', '.vscode', 'dist', 'build', '.wand', 'venv', '.venv', 'python_env', 'bin', 'obj', 'Lib', 'site-packages', 'Include'], max_depth: int = 5) -> list:
    """
    Scans the workspace and returns a list of files with their basic metadata.
    Supports .gitignore, custom ignore list, and smart folding for large directories.

    Args:
        workspace_path (str): Root path to scan.
        ignore_list (list, optional): List of directories/files to ignore. Defaults to standard ignore list.
        max_depth (int, optional): Maximum depth to scan. Defaults to 5.

    Returns:
        list: A list of dictionaries, each containing 'path', 'size' (bytes), and 'last_modified'.
    """
    import os
    import fnmatch
    from datetime import datetime

    file_list = []

    ignore_set = set(ignore_list)

    gitignore_patterns = []
    gitignore_path = os.path.join(workspace_path, '.gitignore')
    if os.path.exists(gitignore_path):
        try:
            with open(gitignore_path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        gitignore_patterns.append(line)
        except Exception:
            pass

    def is_ignored(path, is_dir=False):
        name = os.path.basename(path)
        if name in ignore_set: return True
        if name.startswith('.'): return True

        rel_path = os.path.relpath(path, workspace_path).replace(os.sep, '/')
        for pattern in gitignore_patterns:
            if fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(rel_path, pattern):
                return True
            if is_dir and pattern.endswith('/') and fnmatch.fnmatch(rel_path + '/', pattern):
                return True
        return False

    for root, dirs, files in os.walk(workspace_path):
        rel_root = os.path.relpath(root, workspace_path)
        if rel_root == '.':
            depth = 0
        else:
            depth = rel_root.count(os.sep) + 1

        if depth >= max_depth:
            dirs[:] = []
            continue

        dirs[:] = [d for d in dirs if not is_ignored(os.path.join(root, d), is_dir=True)]

        valid_files = [f for f in files if not is_ignored(os.path.join(root, f))]

        if len(valid_files) > 50:
             file_list.append({
                "path": os.path.join(root, f"< {len(valid_files)} files omitted >"),
                "size": 0,
                "last_modified": "N/A"
             })
             for file in valid_files[:5]:
                file_path = os.path.join(root, file)
                try:
                    stats = os.stat(file_path)
                    file_list.append({
                        "path": file_path,
                        "size": stats.st_size,
                        "last_modified": datetime.fromtimestamp(stats.st_mtime).isoformat()
                    })
                except:
                    pass
        else:
            for file in valid_files:
                file_path = os.path.join(root, file)
                try:
                    stats = os.stat(file_path)
                    file_list.append({
                        "path": file_path,
                        "size": stats.st_size,
                        "last_modified": datetime.fromtimestamp(stats.st_mtime).isoformat()
                    })
                except Exception:
                    file_list.append({"path": file_path, "size": -1, "last_modified": "Unknown"})

    return file_list

