def read_file(file_path: str) -> str:
    """
    Reads the content of a file. 
    Supports text files and PDF (if pypdf is installed).

    Args:
        file_path (str): The absolute path to the file to read. Supports text files and .pdf files.

    Returns:
        str: The content of the file, or an error message if reading fails.
    """
    if not os.path.exists(file_path):
        return f"Error: File not found: {file_path}"

    ext = os.path.splitext(file_path)[1].lower()

    if ext == '.pdf':
        try:
            from pypdf import PdfReader
            reader = PdfReader(file_path)
            text_list = []
            for page in reader.pages:
                text_list.append(page.extract_text())
            return "\n".join(text_list)
        except ImportError:
            return "Error: PDF file detected but pypdf is not installed."
        except Exception as e:
            return f"Error reading PDF: {str(e)}"

    if _is_binary_file(file_path):
        return f"Error: File {os.path.basename(file_path)} appears to be binary."

    try:
        with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
            if len(content) > 50000:
                return content[:50000] + "\n...[Content truncated]..."
            return content
    except Exception as e:
        return f"Error reading file: {str(e)}"

