def list_files(directory_path: str) -> list:
    """
    Lists files in a specific directory.

    Args:
        directory_path (str): The absolute path to the directory to list.

    Returns:
        list: A list of filenames in the directory, or a list containing an error message if the directory does not exist.
    """
    try:
        return os.listdir(directory_path)
    except Exception as e:
        return [f"Error: {str(e)}"]

