def get_workspace_content_index(ignore_list: list = ['.git', 'node_modules', '__pycache__', '.vscode', 'dist', 'build', '.wand', 'venv', '.venv', 'python_env', 'bin', 'obj', 'Lib', 'site-packages', 'Include'], max_depth: int = 5):
    """
    Retrieves and updates the workspace content index with LLM-generated summaries.
    Supports .gitignore, custom ignore list, and smart folding for large directories.

    Difference from 'scan_workspace':
    - 'scan_workspace': Quickly lists file paths and basic metadata (structure only).
    - 'get_workspace_content_index': Analyzes file content to generate semantic summaries, helping the model understand the purpose of each file.

    Args:
        ignore_list (list, optional): List of directories/files to ignore. Defaults to standard ignore list.
        max_depth (int, optional): Maximum depth to scan. Defaults to 5.

    Returns:
        str: The JSON string of the updated workspace index (Merkle Tree), containing file paths and descriptions.
    """
    import os
    import json
    import hashlib
    import fnmatch
    import concurrent.futures
    from datetime import datetime

    # Use current working directory as workspace root
    workspace_path = os.getcwd()

    index_dir = os.path.join(workspace_path, '.wand')
    if not os.path.exists(index_dir):
        os.makedirs(index_dir)

    index_file = os.path.join(index_dir, 'workspace_index.json')

    # Load existing index
    old_index = {}
    if os.path.exists(index_file):
        try:
            with open(index_file, 'r', encoding='utf-8') as f:
                old_index = json.load(f)
        except:
            pass

    new_index = {}

    ignore_set = set(ignore_list)

    gitignore_patterns = []
    gitignore_path = os.path.join(workspace_path, '.gitignore')
    if os.path.exists(gitignore_path):
        try:
            with open(gitignore_path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        gitignore_patterns.append(line)
        except Exception:
            pass

    def is_ignored(path, is_dir=False):
        name = os.path.basename(path)
        if name in ignore_set: return True
        if name.startswith('.'): return True

        rel_path = os.path.relpath(path, workspace_path).replace(os.sep, '/')
        for pattern in gitignore_patterns:
            if fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(rel_path, pattern):
                return True
            if is_dir and pattern.endswith('/') and fnmatch.fnmatch(rel_path + '/', pattern):
                return True
        return False

    # 1. Scan and Calculate Hash
    files_to_process = []

    for root, dirs, files in os.walk(workspace_path):
        rel_root = os.path.relpath(root, workspace_path)
        if rel_root == '.':
            depth = 0
        else:
            depth = rel_root.count(os.sep) + 1

        if depth >= max_depth:
            dirs[:] = []
            continue

        dirs[:] = [d for d in dirs if not is_ignored(os.path.join(root, d), is_dir=True)]

        valid_files = [f for f in files if not is_ignored(os.path.join(root, f))]

        # Smart folding logic
        if len(valid_files) > 50:
             # Add a placeholder entry for omitted files
             omitted_path = os.path.join(root, f"< {len(valid_files)} files omitted >")
             rel_omitted_path = os.path.relpath(omitted_path, workspace_path)
             new_index[rel_omitted_path] = {
                 "hash": "N/A",
                 "path": omitted_path,
                 "description": f"Directory contains {len(valid_files)} files. Only first 5 are indexed.",
                 "last_modified": datetime.now().isoformat()
             }
             # Only process first 5 files
             files_to_process_in_dir = valid_files[:5]
        else:
             files_to_process_in_dir = valid_files

        for file in files_to_process_in_dir:
            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, workspace_path)

            try:
                with open(file_path, 'rb') as f:
                    content = f.read()
                    file_hash = hashlib.md5(content).hexdigest()

                # Check if changed
                if rel_path in old_index and old_index[rel_path].get('hash') == file_hash:
                    new_index[rel_path] = old_index[rel_path]
                else:
                    # Needs update
                    files_to_process.append((rel_path, file_path, file_hash))
            except Exception as e:
                print(f"Error processing {rel_path}: {e}")

    # 2. Generate Descriptions for changed files
    if not LLM_CONFIG:
        return "Error: LLM configuration not set."

    model = LLM_CONFIG.get('highSpeedTextModel') or LLM_CONFIG.get('standardTextModel')
    api_key = LLM_CONFIG.get('apiKey')
    base_url = LLM_CONFIG.get('baseUrl')

    updated_count = 0

    def process_file_item(item):
        rel_path, file_path, file_hash = item

        # Read content (text only)
        if _is_binary_file(file_path):
             return rel_path, {
                "hash": file_hash,
                "path": file_path,
                "description": "[Binary File]"
            }

        try:
            with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
                content = f.read(10000) # Limit context

            prompt = f"Please describe the contents of this file. Keep the description concise and under 300 words. The goal is to allow the LLM to understand what is inside this file from a global perspective.\n\nFile: {rel_path}\n\nContent:\n{content}"

            messages = [{"role": "user", "content": prompt}]

            try:
                response = chat_completion(api_key, base_url, model, messages)
                description = response.strip()
            except Exception as e:
                description = f"Error generating description: {str(e)}"

            return rel_path, {
                "hash": file_hash,
                "path": file_path,
                "description": description,
                "last_modified": datetime.now().isoformat()
            }

        except Exception as e:
             return rel_path, {
                "hash": file_hash,
                "path": file_path,
                "description": f"Error reading file: {str(e)}"
            }

    # Use ThreadPoolExecutor for parallel processing
    if files_to_process:
        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            future_to_file = {executor.submit(process_file_item, item): item for item in files_to_process}
            for future in concurrent.futures.as_completed(future_to_file):
                try:
                    rel_path, result_data = future.result()
                    new_index[rel_path] = result_data
                    updated_count += 1
                except Exception as e:
                    print(f"Error in thread processing: {e}")

    # 3. Save Index
    try:
        with open(index_file, 'w', encoding='utf-8') as f:
            json.dump(new_index, f, indent=2, ensure_ascii=False)
    except Exception as e:
        return f"Error saving index: {str(e)}"

    # Return index without hashes to save context
    sanitized_index = {k: {key: val for key, val in v.items() if key != 'hash'} for k, v in new_index.items()}
    return json.dumps(sanitized_index, ensure_ascii=False)
